package tw.com.tft.documentscanner.imaging;import android.graphics.*;import java.io.*;import tw.com.tft.documentscanner.model.FilterMode;public final class FallbackProcessor{public static Bitmap processPreview(Bitmap s,float[]c,FilterMode m){return crop(s,c,m,2600);}public static File processFull(String p,float[]c,FilterMode m,File o,int max)throws Exception{Bitmap s=ImageLoader.loadPreview(p,max);Bitmap r=crop(s,c,m,max);if(r!=s)s.recycle();File par=o.getParentFile();if(par!=null&&!par.exists())par.mkdirs();try(FileOutputStream f=new FileOutputStream(o)){r.compress(Bitmap.CompressFormat.JPEG,98,f);}r.recycle();return o;}private static Bitmap crop(Bitmap s,float[]c,FilterMode mo,int max){float[]p=c!=null&&c.length==8?c:DocumentDetector.safeInset();float[]sp={p[0]*s.getWidth(),p[1]*s.getHeight(),p[2]*s.getWidth(),p[3]*s.getHeight(),p[4]*s.getWidth(),p[5]*s.getHeight(),p[6]*s.getWidth(),p[7]*s.getHeight()};int w=Math.max(64,Math.round(Math.max(d(sp[4],sp[5],sp[6],sp[7]),d(sp[2],sp[3],sp[0],sp[1])))),h=Math.max(64,Math.round(Math.max(d(sp[2],sp[3],sp[4],sp[5]),d(sp[0],sp[1],sp[6],sp[7]))));int l=Math.max(w,h);if(l>max){float z=max/(float)l;w=Math.max(64,Math.round(w*z));h=Math.max(64,Math.round(h*z));}float[]dp={0,0,w,0,w,h,0,h};Matrix mx=new Matrix();mx.setPolyToPoly(sp,0,dp,0,4);Bitmap o=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(o);Paint pt=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);if(mo!=FilterMode.ORIGINAL){ColorMatrix cm=new ColorMatrix();if(mo==FilterMode.BLACK_WHITE)cm.setSaturation(0);else if(mo==FilterMode.SOFT_WHITE)cm.set(new float[]{1.08f,0,0,0,18,0,1.08f,0,0,18,0,0,1.08f,0,18,0,0,0,1,0});else cm.set(new float[]{1.18f,0,0,0,-20,0,1.18f,0,0,-20,0,0,1.18f,0,-20,0,0,0,1,0});pt.setColorFilter(new ColorMatrixColorFilter(cm));}cv.drawBitmap(s,mx,pt);return o;}private static float d(float a,float b,float c,float d){return(float)Math.hypot(a-c,b-d);}}